void rsr_parking_flash (UInt16 length, UInt8 count)
{	
   rsr_out_action (RSR_PARKING_OUT, 0,length, length, count) ;
}
//--------------------------------------------------------------------------//

void rsr_parking_timeout(void * arg)
{
	switch (rsr_out_ctl(RSR_PARKING_OUT))
    {
		case RSR_OUT_STATE_SET : rsr_parking_on() ; break ; 
      	case RSR_OUT_STATE_CLR : rsr_parking_off(); break ;
        case RSR_OUT_STATE_RDY : rsr_parking_pattern (rsr_vars.prk_pattern) ; // retrieve original pattern after flash  
		default: break ;
	}
}	  

